INSERT INTO api_call_record (
    api_name, caller_id, caller_name, person_type, person_level, person_dept,
    call_time, result_status, gmt_create, gmt_modified
) VALUES (
    #{apiName}, #{callerId}, #{callerName}, #{personType}, #{personLevel}, #{personDept},
    #{callTime}, #{resultStatus}, #{gmtCreate}, #{gmtModified}
)

mapper.select:
SELECT ${column} AS name, COUNT(*) AS callCount
FROM api_call_record
WHERE call_time BETWEEN #{startTime} AND #{endTime}
AND ${column} IS NOT NULL AND ${column} != ''
GROUP BY ${column}
ORDER BY callCount DESC

SELECT id, api_name, caller_id, caller_name, person_type, person_level, person_dept,
       call_time, result_status, gmt_create, gmt_modified
FROM api_call_record
WHERE api_name = #{apiName}
ORDER BY gmt_create DESC
LIMIT #{limit}
